import{_ as i,c as l,o as a,b2 as d}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"字典管理设计（系统管理）","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-09-dict-management-design.md","filePath":"superpowers/specs/2026-05-09-dict-management-design.md"}'),o={name:"superpowers/specs/2026-05-09-dict-management-design.md"};function c(t,e,r,s,n,h){return a(),l("div",null,[...e[0]||(e[0]=[d('<h1 id="字典管理设计-系统管理" tabindex="-1">字典管理设计（系统管理） <a class="header-anchor vp-link" href="#字典管理设计-系统管理" aria-label="Permalink to &quot;字典管理设计（系统管理）&quot;">​</a></h1><h2 id="_1-目标与范围" tabindex="-1">1. 目标与范围 <a class="header-anchor vp-link" href="#_1-目标与范围" aria-label="Permalink to &quot;1. 目标与范围&quot;">​</a></h2><h3 id="_1-1-目标" tabindex="-1">1.1 目标 <a class="header-anchor vp-link" href="#_1-1-目标" aria-label="Permalink to &quot;1.1 目标&quot;">​</a></h3><p>本设计用于落地“字典管理 + 字典项管理”主从能力，提供可维护的数据字典体系，确保：</p><ul><li>字典与字典项分层清晰，关系稳定。</li><li>接口契约统一（读 <code>GET</code>、写 <code>POST</code>）。</li><li>前后端统一使用状态字典 <code>sys_normal_disable</code>（<code>0/1</code>）。</li><li>缓存刷新与导出能力可用且职责明确。</li></ul><h3 id="_1-2-范围" tabindex="-1">1.2 范围 <a class="header-anchor vp-link" href="#_1-2-范围" aria-label="Permalink to &quot;1.2 范围&quot;">​</a></h3><ul><li>覆盖字典类型管理（新增、修改、删除、查看、导出、刷新缓存、进入字典项列表）。</li><li>覆盖字典项管理（新增、修改、删除、查看、导出）。</li><li>覆盖主从路由、接口契约、核心校验与异常处理约束。</li></ul><h3 id="_1-3-非范围" tabindex="-1">1.3 非范围 <a class="header-anchor vp-link" href="#_1-3-非范围" aria-label="Permalink to &quot;1.3 非范围&quot;">​</a></h3><ul><li>不扩展多状态体系（仅 <code>0/1</code>）。</li><li>不引入字典版本管理、审批流或多租户隔离。</li><li>不修改统一响应基础契约 <code>R</code>。</li></ul><h2 id="_2-架构与边界" tabindex="-1">2. 架构与边界 <a class="header-anchor vp-link" href="#_2-架构与边界" aria-label="Permalink to &quot;2. 架构与边界&quot;">​</a></h2><h3 id="_2-1-领域拆分" tabindex="-1">2.1 领域拆分 <a class="header-anchor vp-link" href="#_2-1-领域拆分" aria-label="Permalink to &quot;2.1 领域拆分&quot;">​</a></h3><ul><li><code>dict-type</code>：字典类型主表与管理能力。</li><li><code>dict-data</code>：字典项从表与管理能力。</li></ul><h3 id="_2-2-关系约束" tabindex="-1">2.2 关系约束 <a class="header-anchor vp-link" href="#_2-2-关系约束" aria-label="Permalink to &quot;2.2 关系约束&quot;">​</a></h3><ul><li>字典项必须绑定 <code>dictType</code>。</li><li>字典删除前必须校验是否存在未删除字典项。</li><li>不允许出现脱离 <code>dictType</code> 的孤立字典项。</li></ul><h3 id="_2-3-分层责任" tabindex="-1">2.3 分层责任 <a class="header-anchor vp-link" href="#_2-3-分层责任" aria-label="Permalink to &quot;2.3 分层责任&quot;">​</a></h3><ul><li><code>quickboot-common</code>：复用通用响应、异常与 i18n 能力。</li><li><code>quickboot-web</code>：Controller / Service / Mapper / 领域对象、全局异常映射。</li><li><code>quick-ui</code>：主从页面、路由、交互与导出触发。</li></ul><h2 id="_3-数据模型设计" tabindex="-1">3. 数据模型设计 <a class="header-anchor vp-link" href="#_3-数据模型设计" aria-label="Permalink to &quot;3. 数据模型设计&quot;">​</a></h2><h3 id="_3-1-字典类型表-建议-sys-dict-type" tabindex="-1">3.1 字典类型表（建议：<code>sys_dict_type</code>） <a class="header-anchor vp-link" href="#_3-1-字典类型表-建议-sys-dict-type" aria-label="Permalink to &quot;3.1 字典类型表（建议：`sys_dict_type`）&quot;">​</a></h3><p>核心字段：</p><ul><li><code>dict_id</code>（主键）</li><li><code>dict_name</code>（字典名称）</li><li><code>dict_type</code>（字典类型编码）</li><li><code>status</code>（<code>0</code> 正常 / <code>1</code> 停用）</li><li><code>remark</code></li><li>审计字段（创建人/创建时间/更新人/更新时间）</li><li>逻辑删除字段</li></ul><p>约束：</p><ul><li><code>dict_type</code> 全局唯一（逻辑删除策略下按项目约定实现唯一性）。</li></ul><h3 id="_3-2-字典项表-建议-sys-dict-data" tabindex="-1">3.2 字典项表（建议：<code>sys_dict_data</code>） <a class="header-anchor vp-link" href="#_3-2-字典项表-建议-sys-dict-data" aria-label="Permalink to &quot;3.2 字典项表（建议：`sys_dict_data`）&quot;">​</a></h3><p>核心字段：</p><ul><li><code>dict_code</code>（主键）</li><li><code>dict_type</code>（所属字典类型）</li><li><code>dict_label</code>（数据标签）</li><li><code>dict_value</code>（数据键值）</li><li><code>css_class</code>（样式）</li><li><code>list_class</code>（回显样式）</li><li><code>dict_sort</code>（显示排序）</li><li><code>status</code>（<code>0</code> 正常 / <code>1</code> 停用）</li><li><code>remark</code></li><li>审计字段</li><li>逻辑删除字段</li></ul><p>约束：</p><ul><li><code>dict_type + dict_value</code> 唯一。</li><li>字典项写操作必须带 <code>dictType</code>。</li></ul><h2 id="_4-接口契约设计" tabindex="-1">4. 接口契约设计 <a class="header-anchor vp-link" href="#_4-接口契约设计" aria-label="Permalink to &quot;4. 接口契约设计&quot;">​</a></h2><h3 id="_4-1-总体约定" tabindex="-1">4.1 总体约定 <a class="header-anchor vp-link" href="#_4-1-总体约定" aria-label="Permalink to &quot;4.1 总体约定&quot;">​</a></h3><ul><li>读接口使用 <code>GET</code>。</li><li>写接口统一使用 <code>POST</code>（不使用 <code>PUT</code>/<code>DELETE</code>）。</li><li>入参使用 Jakarta Validation。</li><li>失败通过自定义异常统一映射为 <code>R.error(code, message)</code>。</li></ul><h3 id="_4-2-字典类型接口" tabindex="-1">4.2 字典类型接口 <a class="header-anchor vp-link" href="#_4-2-字典类型接口" aria-label="Permalink to &quot;4.2 字典类型接口&quot;">​</a></h3><ul><li><code>GET /system/dict/type/list</code>：字典类型列表（支持筛选）。</li><li><code>GET /system/dict/type/{dictId}</code>：字典类型详情。</li><li><code>POST /system/dict/type</code>：新增字典类型。</li><li><code>POST /system/dict/type/update</code>：修改字典类型。</li><li><code>POST /system/dict/type/remove/{dictId}</code>：删除字典类型（含从表存在校验）。</li><li><code>POST /system/dict/type/export</code>：导出字典类型列表。</li><li><code>POST /system/dict/type/refresh</code>：刷新全部字典缓存。</li><li><code>POST /system/dict/type/refresh/{dictType}</code>：刷新单个字典类型缓存。</li></ul><h3 id="_4-3-字典项接口" tabindex="-1">4.3 字典项接口 <a class="header-anchor vp-link" href="#_4-3-字典项接口" aria-label="Permalink to &quot;4.3 字典项接口&quot;">​</a></h3><ul><li><code>GET /system/dict/data/list</code>：按 <code>dictType</code> 查询字典项列表。</li><li><code>GET /system/dict/data/{dictCode}</code>：字典项详情。</li><li><code>POST /system/dict/data</code>：新增字典项。</li><li><code>POST /system/dict/data/update</code>：修改字典项。</li><li><code>POST /system/dict/data/remove/{dictCode}</code>：删除字典项。</li><li><code>POST /system/dict/data/export</code>：导出当前 <code>dictType</code> 字典项。</li></ul><h2 id="_5-校验与异常处理" tabindex="-1">5. 校验与异常处理 <a class="header-anchor vp-link" href="#_5-校验与异常处理" aria-label="Permalink to &quot;5. 校验与异常处理&quot;">​</a></h2><h3 id="_5-1-参数校验" tabindex="-1">5.1 参数校验 <a class="header-anchor vp-link" href="#_5-1-参数校验" aria-label="Permalink to &quot;5.1 参数校验&quot;">​</a></h3><ul><li>Controller 必须使用 <code>@Validated</code> / <code>@Valid</code>。</li><li>字段约束至少覆盖：必填、长度、状态枚举、排序范围。</li></ul><h3 id="_5-2-业务校验" tabindex="-1">5.2 业务校验 <a class="header-anchor vp-link" href="#_5-2-业务校验" aria-label="Permalink to &quot;5.2 业务校验&quot;">​</a></h3><ul><li>新增/修改字典类型时校验 <code>dictType</code> 唯一性。</li><li>新增/修改字典项时校验 <code>dictType + dictValue</code> 唯一性。</li><li>删除字典类型前校验是否存在未删除字典项。</li></ul><h3 id="_5-3-异常策略" tabindex="-1">5.3 异常策略 <a class="header-anchor vp-link" href="#_5-3-异常策略" aria-label="Permalink to &quot;5.3 异常策略&quot;">​</a></h3><ul><li>禁止抛 <code>IllegalArgumentException</code> 作为业务失败信号。</li><li>统一抛项目自定义异常（如 <code>WarningException</code>），由全局异常处理映射响应。</li></ul><h2 id="_6-缓存与导出策略" tabindex="-1">6. 缓存与导出策略 <a class="header-anchor vp-link" href="#_6-缓存与导出策略" aria-label="Permalink to &quot;6. 缓存与导出策略&quot;">​</a></h2><h3 id="_6-1-缓存刷新" tabindex="-1">6.1 缓存刷新 <a class="header-anchor vp-link" href="#_6-1-缓存刷新" aria-label="Permalink to &quot;6.1 缓存刷新&quot;">​</a></h3><ul><li>提供“单个类型刷新 + 全量刷新”两种能力。</li><li>刷新后后续查询需读取最新缓存/数据源结果。</li></ul><h3 id="_6-2-导出" tabindex="-1">6.2 导出 <a class="header-anchor vp-link" href="#_6-2-导出" aria-label="Permalink to &quot;6.2 导出&quot;">​</a></h3><ul><li>字典类型页导出字典类型列表。</li><li>字典项页导出当前 <code>dictType</code> 下字典项。</li><li>导出范围与页面筛选条件保持一致（若传筛选）。</li></ul><h2 id="_7-前端页面与路由" tabindex="-1">7. 前端页面与路由 <a class="header-anchor vp-link" href="#_7-前端页面与路由" aria-label="Permalink to &quot;7. 前端页面与路由&quot;">​</a></h2><h3 id="_7-1-路由结构" tabindex="-1">7.1 路由结构 <a class="header-anchor vp-link" href="#_7-1-路由结构" aria-label="Permalink to &quot;7.1 路由结构&quot;">​</a></h3><ul><li><code>/system/dict/type</code>：字典类型管理页。</li><li><code>/system/dict/data/:dictType</code>：字典项管理页。</li></ul><h3 id="_7-2-页面职责" tabindex="-1">7.2 页面职责 <a class="header-anchor vp-link" href="#_7-2-页面职责" aria-label="Permalink to &quot;7.2 页面职责&quot;">​</a></h3><ul><li>字典类型页：新增、修改、删除、查看、导出、刷新缓存、进入字典项列表。</li><li>字典项页：新增、修改、删除、查看、导出。</li></ul><h3 id="_7-3-组件策略" tabindex="-1">7.3 组件策略 <a class="header-anchor vp-link" href="#_7-3-组件策略" aria-label="Permalink to &quot;7.3 组件策略&quot;">​</a></h3><ul><li>优先使用 <code>@/packages</code> 组件（如 <code>C7Button</code>、<code>C7Dialog</code>、<code>C7JsonTable</code>、<code>C7DictTag</code>）。</li><li>权限点建议： <ul><li><code>system:dict:list</code>、<code>system:dict:query</code>、<code>system:dict:add</code>、<code>system:dict:edit</code>、<code>system:dict:remove</code>、<code>system:dict:export</code>、<code>system:dict:refresh</code></li></ul></li></ul><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><h3 id="_8-1-后端验收" tabindex="-1">8.1 后端验收 <a class="header-anchor vp-link" href="#_8-1-后端验收" aria-label="Permalink to &quot;8.1 后端验收&quot;">​</a></h3><ul><li>字典类型 CRUD、字典项 CRUD 可用。</li><li>删除字典类型时，存在字典项则拒绝并返回可读 <code>msg</code>。</li><li>单类型刷新与全量刷新均可执行。</li><li>统一返回 <code>R</code> 契约。</li></ul><h3 id="_8-2-前端验收" tabindex="-1">8.2 前端验收 <a class="header-anchor vp-link" href="#_8-2-前端验收" aria-label="Permalink to &quot;8.2 前端验收&quot;">​</a></h3><ul><li>主从页面可正确跳转并透传 <code>dictType</code>。</li><li>页面操作完整：查看/新增/修改/删除/导出/刷新。</li><li>状态显示与筛选使用 <code>sys_normal_disable</code>。</li></ul><h3 id="_8-3-集成验收" tabindex="-1">8.3 集成验收 <a class="header-anchor vp-link" href="#_8-3-集成验收" aria-label="Permalink to &quot;8.3 集成验收&quot;">​</a></h3><ul><li>删除受限、导出范围、缓存刷新结果与业务预期一致。</li></ul><h2 id="_9-风险与缓解" tabindex="-1">9. 风险与缓解 <a class="header-anchor vp-link" href="#_9-风险与缓解" aria-label="Permalink to &quot;9. 风险与缓解&quot;">​</a></h2><ul><li><p>风险：历史数据导致唯一性冲突。</p><ul><li>缓解：上线前执行数据巡检与冲突清洗。</li></ul></li><li><p>风险：缓存刷新与查询一致性短时抖动。</p><ul><li>缓解：刷新后采用统一缓存更新策略并记录操作日志。</li></ul></li><li><p>风险：前端页面误用接口语义。</p><ul><li>缓解：在 API 层集中封装并固定调用方式。</li></ul></li></ul><h2 id="_10-结论" tabindex="-1">10. 结论 <a class="header-anchor vp-link" href="#_10-结论" aria-label="Permalink to &quot;10. 结论&quot;">​</a></h2><p>采用“主从双页 + 强绑定 <code>dictType</code> + 统一 <code>POST</code> 写接口 + 双刷新 + 分级导出 + packages 优先”的方案，可在不破坏现有契约的前提下稳定落地字典管理能力。</p>',64)])])}const _=i(o,[["render",c]]);export{p as __pageData,_ as default};
